import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    pts = [(0, 0)] * n
    for i in range(n):
        pts[i] = (data[1 + 2*i], data[2 + 2*i])

    # Encode each state as a bitmask. An operation retains the chosen ball
    # and all balls in the two opposite (incomparable) quadrants.
    keep = [[0] * n for _ in range(n)]
    for k, (xk, yk) in enumerate(pts):
        for i, (x, y) in enumerate(pts):
            if i == k or (x < xk and y > yk) or (x > xk and y < yk):
                keep[k][i] = 1 << i

    start = (1 << n) - 1
    seen = {start}
    q = deque([start])
    while q:
        state = q.popleft()
        bits = state
        while bits:
            b = bits & -bits
            k = b.bit_length() - 1
            bits -= b
            nxt = 0
            for j in range(n):
                if state >> j & 1:
                    nxt |= keep[k][j]
            if nxt not in seen:
                seen.add(nxt)
                q.append(nxt)
    print(len(seen) % MOD)

if __name__ == '__main__':
    main()

