    # constraints with that X and R <= r.
    best = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(m):
        l, r, x = vals[3 * i:3 * i + 3]
        if l > best[x][r]:
            best[x][r] = l
    for x in range(1, n + 1):
        row = best[x]
        for r in range(1, n + 1):
            if row[r - 1] > row[r]:
                row[r] = row[r - 1]

    # Binomial coefficients.
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    comb[0][0] = 1
    for a in range(1, n + 1):
        comb[a][0] = comb[a][a] = 1
        for b in range(1, a):
            comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

    # dp[l][r]: valid permutations on positions [l, r]. Empty intervals have 1.
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                # A condition with X=k lies wholly in [l,r] exactly when
                # some such interval has L >= l and R <= r.
                if l <= best[k][r]:
                    continue
                total += comb[length - 1][k - l] * dp[l][k - 1] % MOD * dp[k + 1][r]
            dp[l][r] = total % MOD

    print(dp[1][n])

