import sys
from array import array

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    parent = [x - 1 for x in data[2:]]

    indeg = [0] * n
    for v in parent:
        indeg[v] += 1

    # Remove non-cycle vertices from leaves towards the cycles.
    queue = [i for i in range(n) if indeg[i] == 0]
    acc = [None] * n
    for v in queue:
        values = acc[v]
        if values is None:
            values = array('I', [1]) * m

        # For this vertex, count choices with value at most t.
        prefix = 0
        for t in range(m):
            prefix += values[t]
            if prefix >= MOD:
                prefix -= MOD
            values[t] = prefix

        p = parent[v]
        parent_values = acc[p]
        if parent_values is None:
            acc[p] = values
        else:
            for t in range(m):
                parent_values[t] = parent_values[t] * values[t] % MOD

        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    # Each remaining component has one directed cycle. Its cycle vertices
    # share a common value; distinct components are independent.
    seen = set()
    answer = 1
    for start in range(n):
        if indeg[start] > 0 and start not in seen:
            cycle = []
            v = start
            while v not in seen:
                seen.add(v)
                cycle.append(v)
                v = parent[v]

            ways = 0
            for t in range(m):
                product = 1
                for u in cycle:
                    values = acc[u]
                    if values is not None:
                        product = product * values[t] % MOD
                ways = (ways + product) % MOD
            answer = answer * ways % MOD

    print(answer)

