import sys

MOD = 998244353


def primes_upto(n):
    sieve = [True] * (n + 1)
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i in range(2, n + 1) if sieve[i]]


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]
    primes = primes_upto(1000)
    answer = 1

    for p in primes:
        exponents = []
        occurs = False
        for value in values:
            x = value
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            exponents.append(e)
            occurs |= e > 0
        if not occurs:
            continue

        # dp[h] sums score contributions for the processed prefix, where
        # h is the current height above the prefix's minimum.
        dp = {0: 1}
        processed = 1
        for e in exponents:
            next_dp = {}
            steps = (0,) if e == 0 else (-e, e)
            for height, ways in dp.items():
                for step in steps:
                    new_height = height + step
                    if new_height >= 0:
                        nh = new_height
                        multiplier = pow(p, nh, MOD)
                    else:
                        # The new value makes a lower minimum. Shift the
                        # heights of all processed positions by -new_height.
                        drop = -new_height
                        nh = 0
                        multiplier = pow(p, drop * processed, MOD)
                    next_dp[nh] = (next_dp.get(nh, 0) + ways * multiplier) % MOD
            dp = next_dp
            processed += 1

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    main()

