class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            at[b].append((a, i))

        first = second = 0
        first_id = -1
        first_count = 0
        gain = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, i in at[r]:
                if a > first:
                    second = first
                    first = a
                    first_id = i
                    first_count = 1
                elif a == first:
                    second = first
                    first_count += 1
                elif a > second:
                    second = a

            total += r - first
            if first_count == 1:
                gain[first_id] += first - second

        return total + max(gain, default=0)

